Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <vector>
#include <queue>
#include <cstring>
#include <cstdio>
#include <algorithm>
using namespace std;

const int MAXN=12, INF=1000000;
int dx[4]={-1,1,0,0}, dy[4]={0,0,-1,1};
int N,T;
char grid1[MAXN][MAXN], grid2[MAXN][MAXN];
int A[MAXN][MAXN];
int B[MAXN][MAXN][MAXN][MAXN];

struct Edge {
    int a, b, cap, flow;
};

int n, s, t;
int d[MAX_NETWORK_NODES], ptr[MAX_NETWORK_NODES], q[MAX_NETWORK_NODES];
vector<Edge> e;
vector<int> g[MAX_NETWORK_NODES];

void add_edge(int a, int b, int cap) {
    Edge e1={a,b,cap,0}, e2={b,a,0,0};
    g[a].push_back((int)e.size()); e.push_back(e1);
    g[b].push_back((int)e.size()); e.push_back(e2);
}

bool bfs() {
    int qh=0, qt=0;
    q[qt++]=s;
    memset(d,-1,sizeof(d));
    d[s]=0;
    while(qh<qt && d[t]==-1){
        int v=q[qh++];
        for(auto id:g[v]){
            int to=e[id].b;
            if(d[to]==-1 && e[id].flow<e[id].cap){
                q[qt++]=to;
                d[to]=d[v]+1;
            }
        }
    }
    return d[t]!=-1;
}

int dfs(int v, int flow) {
    if(!flow) return 0;
    if(v==t) return flow;
    for(int &i=ptr[v];i<(int)g[v].size();i++){
        int id=g[v][i], to=e[id].b;
        if(d[to]!=d[v]+1) continue;
        int pushed=dfs(to,min(flow,e[id].cap-e[id].flow));
        if(pushed){
            e[id].flow+=pushed;
            e[id^1].flow-=pushed;
            return pushed;
        }
    }
    return 0;
}

int max_flow() {
    int flow=0;
    while(bfs()){
        memset(ptr,0,sizeof(ptr));
        while(int pushed=dfs(s,INF))
            flow+=pushed;
    }
    return flow;
}

int get_id(int x,int y){ return x*N+y; }

void build_network() {
    s=0; t=2*N*N+1;
    n=2*N*N+2;
    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++){
            if(grid1[i][j]>'0' && grid1[i][j]<='9')
                add_edge(s,1+get_id(i,j),grid1[i][j]-'0');
            if(grid2[i][j]>'0' && grid2[i][j]<='9')
                add_edge(N*N+1+get_id(i,j),t,grid2[i][j]-'0');
        }
    for(int x1=0;x1<N;x1++)
        for(int y1=0;y1<N;y1++)
            for(int x2=0;x2<N;x2++)
                for(int y2=0;y2<N;y2++)
                    if(B[x1][y1][x2][y2]){
                        add_edge(1+get_id(x1,y1),N*N+1+get_id(x2,y2),INF);
                    }
}

int main() {
    scanf("%d%d",&N,&T);
    for(int i=0;i<N;i++) scanf("%s",grid1[i]);
    for(int i=0;i<N;i++) scanf("%s",grid2[i]);
    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++)
            A[i][j]=INF;
    queue<pair<int,int>> Q;
    for(int x=0;x<N;x++)
        for(int y=0;y<N;y++)
            if(grid1[x][y]=='Z'){
                for(int i=0;i<4;i++){
                    int nx=x+dx[i], ny=y+dy[i];
                    if(nx>=0 && nx<N && ny>=0 && ny<N && grid1[nx][ny]!='Y'){
                        A[nx][ny]=1;
                        Q.push({nx,ny});
                    }
                }
            }
    while(!Q.empty()){
        auto p=Q.front(); Q.pop();
        int x=p.first, y=p.second;
        for(int i=0;i<4;i++){
            int nx=x+dx[i], ny=y+dy[i];
            if(nx>=0 && nx<N && ny>=0 && ny<N && grid1[nx][ny]!='Y' && grid1[nx][ny]!='Z' && A[nx][ny]==INF){
                A[nx][ny]=A[x][y]+1;
                Q.push({nx,ny});
            }
        }
    }
    for(int x1=0;x1<N;x1++)
        for(int y1=0;y1<N;y1++)
            for(int x2=0;x2<N;x2++)
                for(int y2=0;y2<N;y2++){
                    if(grid1[x1][y1]=='Y'||grid1[x1][y1]=='Z'||grid1[x2][y2]=='Y'||grid1[x2][y2]=='Z'){
                        B[x1][y1][x2][y2]=0; continue;
                    }
                    for(int i=0;i<N;i++)
                        for(int j=0;j<N;j++)
                            A[i][j]=INF;
                    queue<pair<int,int>> Q2;
                    A[x1][y1]=0; Q2.push({x1,y1});
                    int c=0;
                    while(!Q2.empty()){
                        auto p2=Q2.front(); Q2.pop();
                        int x=p2.first, y=p2.second;
                        if(x==x2 && y==y2){ c=1; break; }
                        if(A[x][y]>=T || A[x][y]>=A[x][y]) continue;
                        for(int i=0;i<4;i++){
                            int nx=x+dx[i], ny=y+dy[i];
                            if(nx>=0 && nx<N && ny>=0 && ny<N && grid1[nx][ny]!='Y' && grid1[nx][ny]!='Z' && A[nx][ny]==INF && A[x][y]+1<=A[nx][ny]){
                                A[nx][ny]=A[x][y]+1;
                                Q2.push({nx,ny});
                            }
                        }
                    }
                    B[x1][y1][x2][y2]=c;
                }
    build_network();
    printf("%d\n",max_flow());
    return 0;
}
